import { test, expect } from '@playwright/test';

test.describe('WebSocket Real-time UI Updates', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should establish WebSocket connection and update UI in real-time', async ({ page }) => {
    // Verify initial state
    const statusIndicator = page.getByRole('status');
    await expect(statusIndicator).toContainText('Connected');

    const messageDisplay = page.getByTestId('message-display');
    await expect(messageDisplay).toContainText('Welcome');

    // Open WebSocket connection
    const connectButton = page.getByRole('button', { name: /connect/i });
    await connectButton.click();

    // Wait for connection confirmation
    await page.waitForResponse(response => 
      response.url().includes('/ws') && response.status() === 100
    );

    // Verify connection status
    await expect(statusIndicator).toContainText('Connected');

    // Listen for real-time message updates
    const messagePromise = page.waitForResponse(response => 
      response.url().includes('/ws') && response.status() === 100
    );

    // Send a message via WebSocket
    const messageInput = page.getByPlaceholder('Type a message...');
    await messageInput.fill('Hello from user');

    const sendButton = page.getByRole('button', { name: /send/i });
    await sendButton.click();

    // Wait for the message to be received and displayed
    const receivedMessage = page.getByTestId('received-message');
    await expect(receivedMessage).toContainText('Hello from user');

    // Verify timestamp is updated
    const timestamp = page.getByTestId('message-timestamp');
    await expect(timestamp).toBeVisible();

    // Verify message count increases
    const messageCount = page.getByTestId('message-count');
    await expect(messageCount).toContainText('1');
  });

  test('should handle WebSocket disconnection and display error state', async ({ page }) => {
    // Verify initial state
    const statusIndicator = page.getByRole('status');
    await expect(statusIndicator).toContainText('Connected');

    // Open WebSocket connection
    const connectButton = page.getByRole('button', { name: /connect/i });
    await connectButton.click();

    // Wait for connection confirmation
    await page.waitForResponse(response => 
      response.url().includes('/ws') && response.status() === 100
    );

    // Simulate WebSocket disconnection
    await page.route('**/ws', route => {
      route.abort('failed');
    });

    // Wait for disconnection event
    await page.waitForTimeout(500);

    // Verify connection status updates to disconnected
    await expect(statusIndicator).toContainText('Disconnected');

    // Verify error message is displayed
    const errorMessage = page.getByTestId('error-message');
    await expect(errorMessage).toBeVisible();
    await expect(errorMessage).toContainText('Connection lost');

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Verify message count is reset or shows no messages
    const messageCount = page.getByTestId('message-count');
    await expect(messageCount).toContainText('0');
  });
});
